// Open opens a connection to the db given a URL
func Open(cfg config.Config) (*sql.DB, Driver, error) {
	sql, driver, err := openConfig(cfg, false)
	if err != nil {
		return nil, 0, err
	}

	sql.SetMaxIdleConns(cfg.Database.MaxIdleConn)

	if cfg.Database.MaxOpenConn > 0 {
		sql.SetMaxOpenConns(cfg.Database.MaxOpenConn)
	}
	if cfg.Database.ConnMaxLifetime > 0 {
		sql.SetConnMaxLifetime(cfg.Database.ConnMaxLifetime)
	}

	registerMetrics(driver, sql)

	return sql, driver, nil
}

func openConfig(cfg config.Config, migrate bool) (*sql.DB, Driver, error) {
	raw, err := connectionTarget(cfg.Database)
	if err != nil {
		return nil, 0, fmt.Errorf("validating database configuration: %w", err)
	}
	return open(raw, migrate)
}

func connectionTarget(c config.DatabaseConfig) (string, error) {
	if err := c.ValidateDatabase(); err != nil {
		return "", err
	}
	if c.URL != "" {
		return c.URL, nil
	}
	if c.Protocol == config.DatabaseSQLite {
		return "file:" + filepath.Join(c.Host, c.Name), nil
	}
	port := c.Port
	if port == 0 {
		if c.Protocol == config.DatabasePostgres {
			port = 5432
		} else {
			port = 3306
		}
	}
	u := &url.URL{Scheme: c.Protocol.String(), Host: net.JoinHostPort(c.Host, strconv.Itoa(port)), Path: "/" + c.Name}
	if c.Password != "" {
		u.User = url.UserPassword(c.User, c.Password)
	} else if c.User != "" {
		u.User = url.User(c.User)
	}
	return u.String(), nil
}

func open(rawurl string, migrate bool) (*sql.DB, Driver, error) {
	d, url, err := parse(rawurl, migrate)
	if err != nil {
		return nil, 0, err
	}

	driverName := fmt.Sprintf("instrumented-%s", d)

	var dr driver.Driver

	switch d {
	case SQLite:
		dr = &sqlite3.SQLiteDriver{}
	case Postgres:
		dr = &pq.Driver{}
	case MySQL:
		dr = &mysql.MySQLDriver{}
	}

	registered := false

	for _, dd := range sql.Drivers() {
		if dd == driverName {
			registered = true
			break
		}
	}

	if !registered {
		sql.Register(driverName, instrumentedsql.WrapDriver(dr, instrumentedsql.WithTracer(opentracing.NewTracer(false))))
	}

	db, err := sql.Open(driverName, url.DSN)
	if err != nil {
		return nil, 0, fmt.Errorf("opening db for driver %s: connection failed", d)
	}

	return db, d, nil
}

var (
	driverToString = map[Driver]string{
		SQLite:   "sqlite3",
		Postgres: "postgres",
		MySQL:    "mysql",
	}

	stringToDriver = map[string]Driver{
		"sqlite3":  SQLite,
		"postgres": Postgres,
		"mysql":    MySQL,
	}
)

// Driver represents a database driver
type Driver uint8

func (d Driver) String() string {
	return driverToString[d]
}

const (
	_ Driver = iota
	// SQLite ...
	SQLite
	// Postgres ...
	Postgres
	// MySQL ...
	MySQL
)

func parse(rawurl string, migrate bool) (Driver, *dburl.URL, error) {
	url, err := dburl.Parse(rawurl)
	if err != nil {
		return 0, nil, fmt.Errorf("parsing db.url: invalid database URL")
	}

	driver := stringToDriver[url.Driver]
	if driver == 0 {
		return 0, nil, fmt.Errorf("parsing db.url: unsupported database driver %q", url.Driver)
	}

	switch driver {
	case MySQL:
		v := url.Query()
		v.Set("multiStatements", "true")
		v.Set("parseTime", "true")
		if !migrate {
			v.Set("sql_mode", "ANSI")
		}
		url.RawQuery = v.Encode()
		// we need to re-parse since we modified the query params
		url, err = dburl.Parse(url.URL.String())

	case SQLite:
		v := url.Query()
		v.Set("cache", "shared")
		v.Set("_fk", "true")
		url.RawQuery = v.Encode()

		// we need to re-parse since we modified the query params
		url, err = dburl.Parse(url.URL.String())
	}

	if err != nil {
		return 0, nil, fmt.Errorf("parsing db.url: invalid database URL")
	}
	return driver, url, nil
}
